import java.io.*;
import java.util.*;

public class Educational {
    public static void main(String[] args) throws IOException {
        Educational app = new Educational();
        app.go();
    }

    private void go() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim().split("\\s+")[0]);
        String str = br.readLine();
        int[] arr = Arrays.stream(br.readLine().trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        char[] chars = str.toCharArray();

        List<Integer> buffer = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == chars[opposite(n, i)]) {
                if (buffer.isEmpty()) {
                    buffer.add(i);
                } else {
                    boolean done = false;
                    for (int j : buffer) {
                        if (chars[j] != chars[i]) {
                            int x = arr[j] < arr[opposite(n, j)] ? j : opposite(n, j);
                            int y = arr[i] < arr[opposite(n, i)] ? i : opposite(n, i);
                            exchange(chars, x, y);
                            arr[x] = 0;
                            arr[y] = 0;
                            buffer.remove(Integer.valueOf(j));
                            done = true;
                            break;
                        }
                    }
                    if (!done) buffer.add(i);
                }
            }
        }

        SortedMap<Integer, Set<Integer>> map = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            map.computeIfAbsent(arr[i], k -> new HashSet<>()).add(i);
        }

        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == chars[opposite(n, i)]) {
                int pivot = arr[i] < arr[opposite(n, i)] ? i : opposite(n, i);
                boolean solved = false;
                for (Map.Entry<Integer, Set<Integer>> entry : map.entrySet()) {
                    for (int k : entry.getValue()) {
                        if (k == i || k == pivot || chars[pivot] == chars[k] || chars[pivot] == chars[opposite(n, k)]) continue;
                        exchange(chars, pivot, k);
                        arr[k] = 0;
                        arr[pivot] = 0;
                        map.get(0).add(k);
                        map.get(0).add(pivot);
                        solved = true;
                        break;
                    }
                    if (solved) break;
                }
                if (chars[i] == chars[opposite(n, i)]) System.out.println("alarma");
            }
        }

        for (int i = 0; i < n / 2; i++) {
            if (chars[i] == chars[opposite(n, i)]) System.out.println("FFFF");
        }

        int sum = 0;
        for (int val : arr) sum += val;
        System.out.println(sum);
    }

    private static int opposite(int n, int i) {
        return n - i - 1;
    }

    private static void exchange(char[] data, int a, int b) {
        char temp = data[a];
        data[a] = data[b];
        data[b] = temp;
    }
}
